import {chartTypes,exampleChart,parseTable,validateData,renderChart,csvText} from './research-model.mjs';
import {keys,list,projects,write,recordTask} from './state.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
let chart,root,ctx,tab='manual',dirty=false,busy=false,controller;
const $=s=>root?.querySelector(s);
export const researchHasWork=()=>!!root?.querySelector('.research-space')&&(dirty||busy);
export function researchRouteGuard(){if(!root?.querySelector('.research-space'))return true;if(busy){ctx.notify('正在处理，请稍候。');return false;}if(dirty&&!confirm('有未保存的图表修改。确定离开并放弃这些修改？'))return false;dirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(researchHasWork()){e.preventDefault();e.returnValue='';}});
export function mountResearch(context,id,projectId){controller?.abort();controller=new AbortController();ctx=context;const loaded=list(keys.drafts).find(d=>String(d.id)===String(id)&&d.tool==='research');chart=loaded?.chart?structuredClone(loaded.chart):exampleChart();chart.id=loaded?.id;chart.projectId=loaded?.projectId||projectId||'';if(loaded&&!loaded.chart){try{const data=parseTable('类别,数值\n'+loaded.material);Object.assign(chart,data,{title:loaded.title,example:false});}catch{ctx.notify('旧图表材料无法转换，请保留原记录并重新输入数据。');chart.id=undefined;}}dirty=false;busy=false;tab='manual';root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});}
function field(key,label,max=60){return `<label>${label}<input data-option="${key}" aria-label="${label}" value="${esc(chart[key])}" maxlength="${max}"></label>`;}
function draw(){root.innerHTML=`<div class="research-space"><div class="hub-heading"><div><h1>科研工具</h1><p>整理研究数据，制作论文与汇报图表。</p></div><a class="btn secondary" href="#assets">${icon('chart',17)} 我的图表</a></div><nav class="research-tools" aria-label="科研工具分类"><button class="active" aria-current="page">${icon('chart',18)} 科研绘图</button><button disabled>研究流程图 <small>在线未开放</small></button><button disabled>科研计算 <small>在线未开放</small></button></nav><div class="research-grid"><section class="card research-card"><div class="hub-card-heading"><h2>数据与项目</h2><span class="hub-badge" id="research-source">${chart.example?'示例数据':'用户数据'}</span></div><div class="research-tabs" role="group" aria-label="数据输入方式">${[['manual','手动输入'],['paste','粘贴表格'],['csv','导入 CSV']].map(([id,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-pressed="${tab===id}">${icon(id==='csv'?'upload':'file',15)} ${n}</button>`).join('')}</div><label class="research-field">所属项目<select data-option="projectId" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${chart.projectId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label class="research-field">图表标题<input data-option="title" aria-label="图表标题" maxlength="120" value="${esc(chart.title)}"></label>${tab==='manual'?`<div class="research-table-wrap"><table class="research-table"><thead><tr><th scope="col">#</th>${chart.headers.map((h,j)=>`<th scope="col"><input data-header="${j}" aria-label="第 ${j+1} 列名称" maxlength="40" value="${esc(h)}"></th>`).join('')}<th scope="col">操作</th></tr></thead><tbody>${chart.rows.map((row,i)=>`<tr><th scope="row">${i+1}</th>${row.map((v,j)=>`<td><input data-row="${i}" data-col="${j}" aria-label="第 ${i+1} 行第 ${j+1} 列" maxlength="${j===0?40:30}" value="${esc(v)}" ${j?'inputmode="decimal"':''}></td>`).join('')}<td><button data-remove-row="${i}" aria-label="移除第 ${i+1} 行" ${chart.rows.length===1?'disabled':''}>×</button></td></tr>`).join('')}</tbody></table></div><div class="research-actions"><button class="btn secondary" data-action="add-row">${icon('plus',14)} 添加行</button><button class="btn secondary" data-action="add-series">${icon('plus',14)} 添加系列</button>${chart.headers.length>2?'<button class="btn secondary" data-action="remove-series">移除最后系列</button>':''}</div>`:tab==='paste'?`<label class="research-field">粘贴 CSV 或制表符表格<textarea id="research-paste" rows="9" maxlength="250000" placeholder="类别,方案 A,方案 B&#10;样本一,18,22"></textarea></label><button class="btn secondary" data-action="apply-paste">应用表格</button><p class="hub-footnote">第一行为表头。应用成功才替换数据；空值与非数字会报错。</p>`:`<label class="research-drop">${icon('upload',32)}<b>${busy?'正在读取…':'点击或拖入 CSV 文件'}</b><span>UTF-8 CSV · 最大 1MB · 最多 200 行、5 个数值系列</span><input type="file" id="research-file" accept=".csv,.tsv,text/csv" aria-label="导入 CSV 文件"></label><p class="hub-footnote">支持逗号 CSV、制表符表格和带引号的单元格。</p>`}<div class="research-data-note"><span>${chart.example?'示例或基于示例修改的数据，不代表真实研究。':'图表仅依据你提供的数值绘制。'}</span><b id="research-count">${chart.rows.length} 行 · ${chart.headers.length-1} 个系列</b></div><div class="research-actions"><button class="btn primary" data-action="save">保存图表</button><button class="btn secondary" data-action="csv">导出数据</button><button class="btn secondary" data-action="new">新建空白</button><button class="btn secondary" data-action="example">使用示例</button></div><p id="research-status" class="hub-footnote" role="status">${dirty?'有未保存修改。':'当前浏览器保存，请及时备份。'}</p></section><section class="card research-card"><div class="hub-card-heading"><h2>图表预览</h2><div class="research-actions"><button class="btn secondary" data-action="svg">导出 SVG</button><button class="btn secondary" data-action="png">导出 PNG</button></div></div><div class="research-tabs" role="group" aria-label="图表类型">${chartTypes.map(([id,n])=>`<button data-type="${id}" class="${chart.type===id?'active':''}" aria-pressed="${chart.type===id}">${n}</button>`).join('')}</div><div id="research-chart" class="research-chart"></div><p id="research-error" class="research-error" role="alert"></p><div class="research-settings">${field('xLabel','X 轴名称')}${field('yLabel','Y 轴名称')}${field('unit','单位',20)}<label>配色<select data-option="palette" aria-label="配色">${[['blue','学术蓝 / 青'],['mono','蓝灰'],['nature','自然配色']].map(([v,n])=>`<option value="${v}" ${chart.palette===v?'selected':''}>${n}</option>`).join('')}</select></label><label>字号<select data-option="fontSize" aria-label="字号">${[12,14,16,18].map(n=>`<option value="${n}" ${chart.fontSize===n?'selected':''}>${n}px</option>`).join('')}</select></label><label>导出尺寸<select data-option="width" aria-label="导出尺寸">${[1200,1600,2400].map(n=>`<option value="${n}" ${chart.width===n?'selected':''}>${n} × ${n*.625}</option>`).join('')}</select></label><label>柱状图系列<select data-option="series" aria-label="柱状图系列">${chart.headers.slice(1).map((h,i)=>`<option value="${i}" ${Number(chart.series)===i?'selected':''}>${esc(h)}</option>`).join('')}</select></label><label class="research-check"><input type="checkbox" data-option="legend" ${chart.legend?'checked':''}> 显示图例</label><label class="research-check"><input type="checkbox" data-option="grid" ${chart.grid?'checked':''}> 显示网格</label></div><p class="hub-footnote">单柱状图展示所选系列；分组和折线展示全部系列。散点图要求第一列为数值 X。长类别名称会缩略，SVG 内含完整数据提示。</p><p class="hub-footnote">样式设置不改变原始数据。多行图表会减少坐标标签，建议先筛选关键数据。</p></section></div><section class="card research-card"><div class="hub-card-heading"><h2>最近图表</h2><a href="#assets">查看全部 →</a></div><div class="research-recents">${list(keys.drafts).filter(d=>d.tool==='research').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(d=>`<a href="#draft/${esc(d.id)}">${icon('chart',24)}<div><b>${esc(d.title)}</b><small>${d.chart?.example?'示例材料 · ':''}${formatDate(d.updatedAt)}</small><span>继续编辑 →</span></div></a>`).join('')||'<div class="research-empty">'+icon('chart',28)+'<p>尚无保存的图表，完成绘图后可在这里继续编辑。</p></div>'}</div></section><div class="research-backup">${icon('shield',22)}<div><b>数据有据，图表可复用</b><p>本地处理，不自动上传；统计检验、显著性分析和云端同步尚未接入。</p></div><button class="btn secondary" data-action="backup">导出图表备份</button></div></div>`;updateChart();bindDrop();}
function mark(){dirty=true;$('#research-status').textContent='有未保存修改，请保存图表或导出备份。';}
function updateChart(){try{const svg=renderChart(chart);$('#research-chart').innerHTML=svg;$('#research-error').textContent='';root.querySelectorAll('[data-action="svg"],[data-action="png"]').forEach(b=>b.disabled=busy);}catch(e){$('#research-chart').innerHTML='<div class="research-empty">'+icon('chart',30)+'<p>请修正数据后查看图表。</p></div>';$('#research-error').textContent=e.message;root.querySelectorAll('[data-action="svg"],[data-action="png"]').forEach(b=>b.disabled=true);}}
function inputChange(e){const t=e.target;if(t.dataset.row!==undefined){chart.rows[Number(t.dataset.row)][Number(t.dataset.col)]=t.value;mark();updateChart();}else if(t.dataset.header!==undefined){chart.headers[Number(t.dataset.header)]=t.value;const options=$('[data-option="series"]').options;for(let i=0;i<options.length;i++)options[i].textContent=chart.headers[i+1];mark();updateChart();}else if(t.dataset.option){let v=t.type==='checkbox'?t.checked:t.value;if(['width','fontSize','series'].includes(t.dataset.option))v=Number(v);chart[t.dataset.option]=v;if(t.dataset.option==='width')chart.height=v*.625;mark();updateChart();}else if(t.id==='research-file')readFile(t.files[0]);}
function freeze(value){root.querySelectorAll('input,select,textarea,button').forEach(el=>{if(value){el.dataset.researchDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.researchDisabled!==undefined){el.disabled=el.dataset.researchDisabled==='true';delete el.dataset.researchDisabled;}});}
function bindDrop(){const drop=$('.research-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一个文件。');readFile(e.dataTransfer.files[0]);});}
function replaceData(parsed,name){if(dirty&&!confirm('替换当前表格数据？建议先保存图表或导出备份。'))return;if(chart.example)chart.title=name==='粘贴表格'?'研究数据图表':name.replace(/\.(csv|tsv)$/i,'').slice(0,120)||'研究数据图表';Object.assign(chart,parsed,{example:false,fileName:name,series:0});if(chart.type==='scatter')chart.type='grouped';mark();tab='manual';draw();ctx.notify('已导入并核对数据格式。');}
async function readFile(file){if(!file||busy)return;if(!/\.(csv|tsv)$/i.test(file.name)||file.size>1024*1024)return ctx.notify('请选择 1MB 以内的 CSV 或 TSV。');busy=true;freeze(true);try{const text=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());const parsed=parseTable(text);busy=false;replaceData(parsed,file.name);}catch(e){ctx.notify(e.message||'读取失败，请使用 UTF-8 CSV。');}finally{busy=false;freeze(false);}}
function save(){try{renderChart(chart);const rows=list(keys.drafts),old=rows.find(d=>String(d.id)===String(chart.id)),now=new Date().toISOString(),id=chart.id||crypto.randomUUID(),item={...old,id,title:chart.title.trim(),tool:'research',kind:'科研图表',projectId:chart.projectId,stage:'chart',createdAt:old?.createdAt||now,updatedAt:now,date:formatDate(now),text:csvText(chart),material:csvText(chart),chart:structuredClone({...chart,id})};write(keys.drafts,old?rows.map(d=>d.id===old.id?item:d):[item,...rows]);chart.id=id;dirty=false;try{recordTask({id:'draft-'+id,title:item.title,kind:'科研图表保存',status:'completed',projectId:item.projectId,url:'#draft/'+id});}catch{}draw();ctx.notify('图表和原始数据已保存到当前浏览器。');}catch(e){ctx.notify(e.message||'保存失败，请导出备份。');}}
async function png(){const svg=renderChart(chart),blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);busy=true;freeze(true);try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(new Error('PNG 绘制失败，请导出 SVG。'));img.src=url;});const canvas=document.createElement('canvas');canvas.width=chart.width;canvas.height=chart.height;const context=canvas.getContext('2d');if(!context)throw new Error('当前浏览器无法导出 PNG，请导出 SVG。');context.drawImage(img,0,0);const imageBlob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!imageBlob)throw new Error('PNG 生成失败。');download(chart.title+'.png',imageBlob,'image/png');ctx.notify('已导出 PNG。');}finally{URL.revokeObjectURL(url);busy=false;freeze(false);}}
async function actions(e){const b=e.target.closest('button');if(!b)return;if(busy)return ctx.notify('正在处理，请稍候。');try{if(b.dataset.tab){tab=b.dataset.tab;draw();return;}if(b.dataset.type){chart.type=b.dataset.type;mark();draw();return;}if(b.dataset.removeRow!==undefined){chart.rows.splice(Number(b.dataset.removeRow),1);mark();draw();return;}switch(b.dataset.action){case 'add-row':if(chart.rows.length>=200)throw new Error('最多 200 行。');chart.rows.push(chart.headers.map(()=>''));mark();draw();break;case 'add-series':if(chart.headers.length>=6)throw new Error('最多 5 个数值系列。');chart.headers.push('系列 '+chart.headers.length);chart.rows.forEach(r=>r.push(''));mark();draw();break;case 'remove-series':if(!confirm('移除最后一个系列及其数值？未保存前不影响原有记录。'))return;chart.headers.pop();chart.rows.forEach(r=>r.pop());chart.series=Math.min(chart.series,chart.headers.length-2);mark();draw();break;case 'apply-paste':replaceData(parseTable($('#research-paste').value),'粘贴表格');break;case 'save':save();break;case 'svg':download(chart.title+'.svg',renderChart(chart),'image/svg+xml;charset=utf-8');ctx.notify('已导出 SVG。');break;case 'png':await png();break;case 'csv':download((chart.title||'图表数据')+'.csv',csvText(chart),'text/csv;charset=utf-8');ctx.notify('已导出数据。');break;case 'backup':download((chart.title||'图表')+'-PaperKnow.json',JSON.stringify(chart,null,2),'application/json');break;case 'new':case 'example':if(dirty&&!confirm('放弃当前未保存的图表修改？'))return;chart=exampleChart();if(b.dataset.action==='new')Object.assign(chart,{title:'',headers:['类别','数值'],rows:[['','']],type:'bar',example:false,xLabel:'类别'});dirty=false;tab='manual';draw();break;}}catch(error){ctx.notify(error.message||'操作失败。');}}
